<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';import {useApplication} from '../../application';import {useMaterials,useKnowledgeMaterials} from './useMaterials';import KnowledgeMaterialPicker from './KnowledgeMaterialPicker.vue';import Icon from '../../shared/Icon.vue';
const props=defineProps<{meetingId:string;locked?:boolean}>();const emit=defineEmits<{state:[value:{busy:boolean;blocked:boolean;failed:boolean;hasFiles:boolean;closeBlocked:boolean}]}>();const {session,materials:api,journals}=useApplication();const actor=()=>session.current.value?.actor.enterpriseId??null;const material=useMaterials(api,actor,()=>props.meetingId,journals,()=>!props.locked,()=>{picker.clear();picker.close();});const picker=useKnowledgeMaterials(api,actor,()=>props.meetingId,journals);const localError=ref<string|null>(null),originalFile=ref<string|null>(null),fileInput=ref<HTMLInputElement>(),pickerOpen=ref(false);const state=computed(()=>material.state.value);watch(state,value=>emit('state',value),{immediate:true});
async function act(action:()=>Promise<unknown>){localError.value=null;try{await action();}catch(cause){localError.value=cause instanceof Error?cause.message:'材料操作未完成，请重试原请求。';}}
function chooseLocal(){if(!props.locked){originalFile.value=null;fileInput.value?.click();}}function chooseOriginal(id:string){if(!props.locked){originalFile.value=id;fileInput.value?.click();}}async function selected(event:Event){const drop=event as DragEvent;const input=event.target as HTMLInputElement|null;const files=[...(drop.dataTransfer?.files??input?.files??[])];if(input)input.value='';if(!files.length)return;const job=originalFile.value;originalFile.value=null;await act(()=>job?material.retryJob(job,files[0]):material.addLocal(files));}async function confirmKnowledge(documents:readonly any[]){try{const added=await material.addKnowledge(documents);picker.settle(added);if(added.length===documents.length){pickerOpen.value=false;picker.close();}}catch{} }function openPicker(){if(!props.locked)pickerOpen.value=true;}function remove(id:string){void act(()=>material.remove(id));}function retry(id:string){void act(()=>material.retry(id));}function retryJob(id:string){void act(()=>material.retryJob(id));}function discardJob(id:string){const batch=material.jobs.value.find(job=>job.id===id)?.kind==='BATCH';void act(async()=>{await material.removeJob(id);if(batch)openPicker();});}defineExpose({reload:material.reload,ensureReady:material.ensureReady});onUnmounted(()=>{material.dispose();picker.dispose();});
function parseError(code:string){return ({ARCHIVE_EXPANSION_EXCEEDED:'文档解压后的内容超过安全解析限额，请拆分文件。',NO_TEXT:'未提取到可读文字。扫描件暂不支持 OCR，请提供包含文本的文档。',FORMAT_UNSUPPORTED:'暂不支持该格式，请提供 PDF、PPTX 或 DOCX。',INVALID_DOCUMENT:'文件内容或格式损坏，请检查原文件后重新上传。',DOCUMENT_ENCRYPTED:'加密或禁止提取文字的文档无法解析，请提供可读取的版本。',SOURCE_HASH_MISMATCH:'文件内容与上传记录不一致，请重新上传原文件。',SOURCE_BYTES_EXCEEDED:'文件超过解析大小限制，请缩小文件后重试。',UNITS_EXCEEDED:'文档页数或段落数超过解析限制，请拆分文件。'} as Record<string,string>)[code]??'该材料未能解析，请检查文件后重试。';}
</script>
<template><section class="aci-import-section material-import-section"><div class="ac-material-heading"><h3>会议背景材料及相关文档</h3><div class="flex wrap"><button type="button" class="btn" :disabled="locked||state.busy||!material.ready.value" @click="chooseLocal">上传本地文件</button><button type="button" class="btn" :disabled="locked||state.busy||!material.ready.value" @click="openPicker">从知识库选择</button></div></div><div class="small muted mb12">补充材料有助于更精准理解会议内容和生成纪要；未添加时，将基于会议录音或转写内容处理。</div><div data-aci-files="material"><div v-for="job in material.jobs.value" :key="job.id" class="file-item ac-file material-job"><div class="f-ico"><Icon name="file" :size="20"/></div><div class="ac-file-main"><div class="f-name" :title="job.name">{{job.name}}</div><div class="f-meta">{{['KNOWLEDGE','BATCH'].includes(job.kind)?'知识库引用':'本地文件'}} · {{job.status}}</div><div v-if="job.error" class="ac-error small mt8" role="alert">{{job.error}}</div></div><div class="flex wrap"><button v-if="job.needsFile" type="button" class="btn sm" :disabled="locked||state.busy||!material.ready.value" @click="chooseOriginal(job.id)">重新选择原文件</button><button v-if="job.error&&!job.needsFile" type="button" class="btn sm" :disabled="locked||state.busy||!material.ready.value" @click="retryJob(job.id)">{{job.command?'查回原请求':'重试'}}</button><button v-if="job.canRemove" type="button" class="btn sm ghost" @click="discardJob(job.id)">{{job.kind==='BATCH'?'重新选择文件':'移除'}}</button></div></div><div v-for="item in material.items.value" :key="item.id" class="file-item ac-file"><div class="f-ico"><Icon :name="item.source==='KNOWLEDGE'?'layers':'file'" :size="20"/></div><div class="ac-file-main"><div class="f-name" :title="item.name">{{item.name}}</div><div class="f-meta">{{item.name.split('.').pop()?.toUpperCase()}} · {{item.source==='KNOWLEDGE'?'知识库引用 · '+(item.sourceVersion?.slice(0,12)??'版本未知'):'本地文件'}} · {{item.sizeBytesToken}} B</div><div v-if="item.error" class="ac-error small mt8" role="alert">{{parseError(item.error)}}</div></div><div class="flex wrap"><button v-if="item.state==='FAILED'" type="button" class="btn sm" @click="retry(item.id)">重试解析</button><button type="button" class="btn sm ghost" @click="remove(item.id)">移除</button></div></div></div><div class="upload-zone ac-material-drop" :class="{'has-files':material.items.value.length||material.jobs.value.length}" role="button" tabindex="0" @click="chooseLocal" @keydown.enter.prevent="chooseLocal" @keydown.space.prevent="chooseLocal" @dragover.prevent @drop.prevent="selected"><span v-if="material.items.value.length||material.jobs.value.length">继续拖入背景材料，也可从知识库选择</span><span v-else>可拖入背景材料，也可从知识库选择；无材料可直接开始处理。</span></div><input ref="fileInput" hidden :multiple="originalFile===null" type="file" aria-label="选择背景材料" :disabled="locked||state.busy||!material.ready.value" accept=".pdf,.pptx,.docx" @change="selected"/><div v-if="material.error.value||localError" class="aci-import-error ac-error" role="alert">{{localError??material.error.value}} <button type="button" class="btn sm" :disabled="state.busy||locked" @click="act(material.reload)">重新读取材料</button></div><div v-if="material.listing.value?.materialsPending" class="small ac-error mt8" role="status">材料解析尚未完成，请重试失败材料或移除后再开始处理。</div></section><KnowledgeMaterialPicker :open="pickerOpen" :picker="picker" :busy="state.busy" @close="pickerOpen=false" @confirm="confirmKnowledge"/></template>
